def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    # The most common cell color is the region's background.
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    sep_rows = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != bg]

    def regions(size, separators):
        out, start = [], 0
        for p in separators:
            if start < p:
                out.append((start, p))
            start = p + 1
        if start < size:
            out.append((start, size))
        return out

    rr = regions(h, sep_rows)
    cc = regions(w, sep_cols)

    # Find the tile containing the most non-background cells.
    best = None
    best_score = -1
    for r0, r1 in rr:
        for c0, c1 in cc:
            score = sum(grid[r][c] != bg
                        for r in range(r0, r1)
                        for c in range(c0, c1))
            if score > best_score:
                best_score = score
                best = (r0, r1, c0, c1)

    if best is None or best_score == 0:
        return [row[:] for row in grid]

    r0, r1, c0, c1 = best
    tile = [row[c0:c1] for row in grid[r0:r1]]
    out = [row[:] for row in grid]

    for a, b in rr:
        for x, y in cc:
            for r in range(a, b):
                for c in range(x, y):
                    out[r][c] = tile[(r - a) % len(tile)][(c - x) % len(tile[0])]

    return out
